import crypto from "node:crypto";

/**
 * Shared secret between the chat route and the MCP endpoint it exposes.
 *
 * The endpoint runs on localhost without a login, and one of its tools writes
 * to the database. A page open in the same browser cannot read a cross-origin
 * response, but it can fire the request — and a DNS-rebinding trick would let it
 * read one too. A token minted per process closes both: only the `claude`
 * process we spawn ourselves is handed it.
 */
export const MCP_TOKEN: string =
  process.env.STOCKS_MCP_TOKEN?.trim() || crypto.randomBytes(24).toString("hex");

export const MCP_TOOL_PREFIX = "mcp__akcie__";

/**
 * Header carrying a data cut-off for backtest runs.
 *
 * It rides on the MCP request rather than in the tool schema on purpose: the
 * model configures nothing here, so it cannot widen its own horizon — the
 * server clamps every answer to this date.
 */
export const MCP_CUTOFF_HEADER = "x-stocks-cutoff";
